1	#!/usr/bin/env node
2	'use strict';
3	
4	/**
5	 * PreToolUse:Agent hook — enforces model routing during orchestrations.
6	 *
7	 * Blocks any Agent() call that omits the `model` parameter or uses
8	 * model="inherit" while an orchestration is active. Fails open on all
9	 * unexpected errors so a broken hook never blocks legitimate work.
10	 *
11	 * 2.0.12 additions:
12	 *   - Explicit dispatch allowlist replaces the `toolName !== 'Agent'` fast-exit.
13	 *     Known agent-dispatch names: {Agent, Explore, Task}.
14	 *     Known skip names: {Bash, Read, Edit, Glob, Grep, Write, NotebookEdit,
15	 *       WebFetch, WebSearch, TodoWrite}. Unknown names are handled by
16	 *     `mcp_enforcement.unknown_tool_policy` (default: "block").
17	 *   - `global_kill_switch` short-circuits before ANY 2.0.12 check. Routing.jsonl
18	 *     (2.0.11) validation still runs on known dispatch names.
19	 *   - MCP checkpoint pre-decomposition gate: after routing.jsonl validation,
20	 *     verifies that the PM called the required pre-decomposition MCP tools
21	 *     (pattern_find, kb_search, history_find_similar_tasks) for this
22	 *     orchestration_id before the first Agent() spawn.
23	 *
24	 * Input:  JSON on stdin (Claude Code PreToolUse hook payload)
25	 * Output: exit 0 (allow) or exit 2 (block) with stderr message
26	 */
27	
28	const fs = require('fs');
29	const path = require('path');
30	const { resolveSafeCwd } = require('./_lib/resolve-project-cwd');
31	const { getCurrentOrchestrationFile } = require('./_lib/orchestration-state');
32	const { getRoutingFilePath, findRoutingEntry, readRoutingEntries } = require('./_lib/routing-lookup');
33	const { loadMcpEnforcement, loadRoutingGateConfig, loadAntiPatternGateConfig, loadPatternDecayConfig } = require('./_lib/config-schema');
34	const {
35	  REQUIRED_PRE_DECOMPOSITION_TOOLS,
36	  getCheckpointFilePath,
37	  findCheckpointsForOrchestration,
38	  missingRequiredToolsFromRows,
39	} = require('./_lib/mcp-checkpoint');
40	const { atomicAppendJsonl } = require('./_lib/atomic-append');
41	const { writeEvent }        = require('./_lib/audit-event-writer');
42	const { MAX_INPUT_BYTES } = require('./_lib/constants');
43	const { readCache: readCustomAgentsCache } = require('./_lib/custom-agents');
44	const { CANONICAL_AGENTS } = require('./_lib/canonical-agents');
45	const { readHookInputRaw } = require('./_lib/hook-stdin');
46	
47	const VALID_TIERS = ['fable', 'haiku', 'sonnet', 'opus'];
48	
49	function isValidModel(model) {
50	  const m = model.toLowerCase();
51	  return VALID_TIERS.some(tier => m.includes(tier));
52	}
53	
54	// v2.2.9 B-5.3: gate stdin reader behind require.main check so test imports
55	// of helper exports (computeGroupBoundaryViolation, parseTaskGraphGroups,
56	// compareGroupOrder) don't block on stdin.
57	if (require.main === module) {
58	  let input = '';
59	  input = readHookInputRaw();
60	  if (input.length > MAX_INPUT_BYTES) {
61	    process.stderr.write('[orchestray] hook stdin exceeded ' + MAX_INPUT_BYTES + ' bytes; aborting\n');
62	    process.exit(0);
63	  }
64	  setImmediate(() => {
65	  try {
66	    const event = JSON.parse(input);
67	
68	    // Explicit dispatch allowlist. 2.0.12 closes the Explore/Task bypass by routing
69	    // known agent-dispatch tool names through this gate. Anything else is either a
70	    // known non-agent built-in (Bash, Read, Edit, Glob, Grep, Write — skip) or an
71	    // unknown name (fail-closed by default per unknown_tool_policy; user can
72	    // override in .orchestray/config.json).
73	    const toolName = event.tool_name || (event.tool_input && event.tool_input.tool) || '';
74	
75	    const AGENT_DISPATCH_ALLOWLIST = new Set(['Agent', 'Explore', 'Task']);
76	    const SKIP_ALLOWLIST = new Set([
77	      'Bash', 'Read', 'Edit', 'Glob', 'Grep', 'Write',
78	      'NotebookEdit', 'WebFetch', 'WebSearch', 'TodoWrite',
79	    ]);
80	
81	    if (SKIP_ALLOWLIST.has(toolName)) {
82	      process.exit(0);
83	    }
84	
85	    // Not a known agent-dispatch OR skip tool — defer decision to unknown_tool_policy
86	    // AFTER config is loaded (see below).
87	    const isKnownDispatch = AGENT_DISPATCH_ALLOWLIST.has(toolName);
88	
89	    const cwd = resolveSafeCwd(event.cwd);
90	    const mcpEnforcement = loadMcpEnforcement(cwd);
91	
92	    // Global kill switch — short-circuits before ANY 2.0.12 check. Routing.jsonl
93	    // (2.0.11) validation still runs on known dispatches. D5 property.
94	    if (mcpEnforcement.global_kill_switch === true && isKnownDispatch) {
95	      // In kill-switch mode, we still enforce 2.0.11 model-validity checks on
96	      // known dispatches but skip the new 2.0.12 MCP-checkpoint gate entirely.
97	      // Emit kill_switch_activated event for observability (I-SE-3).
98	      try {
99	        writeEvent({
100	          type:           'kill_switch_activated',
101	          version:        1,
102	          schema_version: 1,
103	          timestamp:      new Date().toISOString(),
104	          switch_name:    'global_kill_switch',
105	          tool_name:      toolName,
106	          source:         'gate-agent-spawn',
107	        }, { cwd });
108	      } catch (_ksEvErr) { /* fail-open */ }
109	      // Fall through to the existing routing.jsonl validation below.
110	    } else if (mcpEnforcement.global_kill_switch === true) {
111	      // Kill switch on AND unknown tool — just exit 0 (degraded to 2.0.11 behavior).
112	      // Emit kill_switch_activated event for observability (I-SE-3).
113	      try {
114	        writeEvent({
115	          type:           'kill_switch_activated',
116	          version:        1,
117	          schema_version: 1,
118	          timestamp:      new Date().toISOString(),
119	          switch_name:    'global_kill_switch',
120	          tool_name:      toolName,
121	          source:         'gate-agent-spawn',
122	        }, { cwd });
123	      } catch (_ksEvErr) { /* fail-open */ }
124	      process.exit(0);
125	    } else {
126	      // Unknown-tool policy (only when NOT in kill-switch mode)
127	      if (!isKnownDispatch) {
128	        const policy = mcpEnforcement.unknown_tool_policy || 'block';
129	        if (policy === 'allow') {
130	          process.exit(0);
131	        }
132	        if (policy === 'warn') {
133	          process.stderr.write(
134	            "[orchestray] unknown tool name '" + toolName + "' in PreToolUse — " +
135	            "allowing per unknown_tool_policy=warn. Add to AGENT_DISPATCH_ALLOWLIST " +
136	            "or SKIP_ALLOWLIST in bin/gate-agent-spawn.js to silence.\n"
137	          );
138	          process.exit(0);
139	        }
140	        // policy === 'block' (default per Q1)
141	        process.stderr.write(
142	          "[orchestray] unknown tool name '" + toolName + "' in PreToolUse — " +
143	          "blocking per unknown_tool_policy=block. If this is a legitimate Claude Code " +
144	          "built-in, add it to AGENT_DISPATCH_ALLOWLIST (to gate it) or SKIP_ALLOWLIST " +
145	          "(to skip gating) in bin/gate-agent-spawn.js. Emergency override: set " +
146	          "mcp_enforcement.unknown_tool_policy to 'warn' in .orchestray/config.json.\n"
147	        );
148	        process.exit(2);
149	      }
150	    }
151	
152	    // From here on: toolName is a known agent-dispatch name (Agent, Explore, or Task),
153	    // or kill-switch mode is active. Proceed with 2.0.11 routing.jsonl validation.
154	
155	    const orchFile = getCurrentOrchestrationFile(cwd);
156	
157	    // -----------------------------------------------------------------------
158	    // v2.3.1 §6.2: Custom-agents spawn gate — fail-closed for unknown types.
159	    //
160	    // For Agent() calls only (not Explore/Task which carry no subagent_type):
161	    // if the requested subagent_type is not a shipped canonical agent AND not in
162	    // the custom-agents cache written by bin/discover-custom-agents.js, reject.
163	    //
164	    // This is the sole authority on which agent types are allowed — the PM
165	    // frontmatter no longer carries a parenthetical allowlist.
166	    //
167	    // Fail-open: any error in the cache-read path allows the spawn.
168	    // Kill switches: ORCHESTRAY_DISABLE_CUSTOM_AGENTS (env) or
169	    //   custom_agents.enabled: false (config) — per design §17.1/§17.2.
170	    //   No emergency fail-open override exists by design (fail-closed is the
171	    //   security requirement; master switch is the only opt-out).
172	    // -----------------------------------------------------------------------
173	    if (toolName === 'Agent') {
174	      try {
175	        const gateToolInput = event.tool_input || {};
176	        const gateSubagentType = gateToolInput.subagent_type || '';
177	        if (gateSubagentType && !CANONICAL_AGENTS.has(gateSubagentType)) {
178	          // Not a shipped canonical agent — check custom-agents cache.
179	          // readCustomAgentsCache never throws and never returns null; it returns
180	          // a safe empty struct {agents: []} on any read/parse failure.
181	          let isAllowed = false;
182	          try {
183	            const cache = readCustomAgentsCache(cwd);
184	            if (Array.isArray(cache.agents)) {
185	              isAllowed = cache.agents.some(a => a && a.name === gateSubagentType);
186	            }
187	            // §3.3: stderr hint when cache is >7 days old (does not invalidate).
188	            if (cache.discovered_at) {
189	              const ageMs = Date.now() - new Date(cache.discovered_at).getTime();
190	              if (Number.isFinite(ageMs) && ageMs > 7 * 24 * 60 * 60 * 1000) {
191	                process.stderr.write(
192	                  '[orchestray] custom-agents: cache is >7 days old; ' +
193	                  'restart Claude Code to refresh discovered agents\n'
194	                );
195	              }
196	            }
197	          } catch (_cacheErr) {
198	            // Cache read failed — fail-closed: treat as unknown.
199	          }
200	          if (!isAllowed) {
201	            const rejectMsg =
202	              '[orchestray] gate-agent-spawn: unknown subagent_type "' + gateSubagentType + '" — ' +
203	              'not a shipped agent role and not found in the custom-agents cache. ' +
204	              'To add a custom agent, create: ' +
205	              '~/.claude/orchestray/custom-agents/' + gateSubagentType + '.md ' +
206	              'then restart the Claude Code session. ' +
207	              'To disable custom-agent gating entirely, set ORCHESTRAY_DISABLE_CUSTOM_AGENTS=1.';
208	            process.stderr.write(rejectMsg + '\n');
209	            try {
210	              writeEvent({
211	                type:            'custom_agents_spawn_rejected',
212	                version:         1,
213	                schema_version:  1,
214	                timestamp:       new Date().toISOString(),
215	                subagent_type:   gateSubagentType,
216	                source:          'gate-agent-spawn',
217	              }, { cwd });
218	            } catch (_evErr) { /* fail-open on emit */ }
219	            process.stdout.write(JSON.stringify({
220	              hookSpecificOutput: {
221	                hookEventName: 'PreToolUse',
222	                permissionDecision: 'deny',
223	                permissionDecisionReason: rejectMsg,
224	              },
225	            }));
226	            process.exit(2);
227	          }
228	        }
229	      } catch (_customGateErr) {
230	        // Fail-open: any unexpected error allows the spawn.
231	      }
232	    }
233	
234	    // P3.3 (v2.2.0): orchestray-housekeeper spawn gate — Clause 3 + Clause 5.
235	    // Refuse if quarantine sentinel exists (drift detector controlled),
236	    // env kill switch is set, or config flag is false. Runs BEFORE the
237	    // orchestration check so it applies in any session state.
238	    {
239	      const earlyToolInput = event.tool_input || {};
240	      const earlySubagentType = earlyToolInput.subagent_type || '';
241	      if (earlySubagentType === 'orchestray-housekeeper') {
242	        const sentinelPath = path.join(cwd, '.orchestray', 'state', 'housekeeper-quarantined');
243	        if (fs.existsSync(sentinelPath)) {
244	          const quarantineMsg =
245	            '[orchestray] gate-agent-spawn: orchestray-housekeeper spawn blocked — ' +
246	            'quarantine sentinel present. Resolve baseline drift before re-enabling. ' +
247	            'See agents/pm-reference/haiku-routing.md §23f.';
248	          process.stderr.write(quarantineMsg + '\n');
249	          process.stdout.write(JSON.stringify({
250	            hookSpecificOutput: {
251	              hookEventName: 'PreToolUse',
252	              permissionDecision: 'deny',
253	              permissionDecisionReason: quarantineMsg,
254	            },
255	          }));
256	          process.exit(2);
257	        }
258	        if (process.env.ORCHESTRAY_HOUSEKEEPER_DISABLED === '1') {
259	          const envMsg =
260	            '[orchestray] gate-agent-spawn: orchestray-housekeeper disabled by env ' +
261	            '(ORCHESTRAY_HOUSEKEEPER_DISABLED=1).';
262	          process.stderr.write(envMsg + '\n');
263	          process.stdout.write(JSON.stringify({
264	            hookSpecificOutput: {
265	              hookEventName: 'PreToolUse',
266	              permissionDecision: 'deny',
267	              permissionDecisionReason: envMsg,
268	            },
269	          }));
270	          process.exit(2);
271	        }
272	        try {
273	          const cfgRaw = fs.readFileSync(path.join(cwd, '.orchestray', 'config.json'), 'utf8');
274	          const cfg = JSON.parse(cfgRaw);
275	          if (cfg && cfg.haiku_routing &&
276	              cfg.haiku_routing.housekeeper_enabled === false) {
277	            const cfgMsg =
278	              '[orchestray] gate-agent-spawn: orchestray-housekeeper disabled in config ' +
279	              '(haiku_routing.housekeeper_enabled = false).';
280	            process.stderr.write(cfgMsg + '\n');
281	            process.stdout.write(JSON.stringify({
282	              hookSpecificOutput: {
283	                hookEventName: 'PreToolUse',
284	                permissionDecision: 'deny',
285	                permissionDecisionReason: cfgMsg,
286	              },
287	            }));
288	            process.exit(2);
289	          }
290	        } catch (_cfgErr) { /* fail-open — default-on per locked-scope D-5 */ }
291	
292	        // S-009 (v2.2.0 fix-pass): housekeeper marker path-prefix check.
293	        // OQ-D1 (in-scope per design) — defence-in-depth against a
294	        // misaddressed [housekeeper: write <path>] marker. The housekeeper
295	        // tool list (Read, Glob) limits damage to "read sensitive file →
296	        // return bytes in Structured Result", but the gate is the cleanest
297	        // place to enforce that any `[housekeeper: write <path>]` marker
298	        // names a path under `.orchestray/kb/artifacts/`. Reject otherwise.
299	        // Non-`write` markers (regen-schema-shadow, rollup-recompute) carry
300	        // no path and pass through.
301	        const description = (earlyToolInput.description || '');
302	        if (typeof description === 'string') {
303	          const writeMarker = description.match(/\[housekeeper:\s*write\s+([^\]]+)\]/);
304	          if (writeMarker && writeMarker[1]) {
305	            const requestedPath = writeMarker[1].trim();
306	            const ARTIFACTS_PREFIX = path.join('.orchestray', 'kb', 'artifacts');
307	            const artifactsAbs = path.resolve(cwd, ARTIFACTS_PREFIX);
308	            const requestedAbs = path.isAbsolute(requestedPath)
309	              ? path.resolve(requestedPath)
310	              : path.resolve(cwd, requestedPath);
311	            const inside = requestedAbs === artifactsAbs ||
312	              requestedAbs.startsWith(artifactsAbs + path.sep);
313	            if (!inside) {
314	              const markerMsg =
315	                '[orchestray] gate-agent-spawn: orchestray-housekeeper marker path ' +
316	                'outside .orchestray/kb/artifacts/ — refusing to spawn. ' +
317	                'Marker path: ' + JSON.stringify(requestedPath) + '. ' +
318	                'Per OQ-D1 of locked-scope D-5, write markers MUST stay within ' +
319	                'the artifacts directory.';
320	              process.stderr.write(markerMsg + '\n');
321	              process.stdout.write(JSON.stringify({
322	                hookSpecificOutput: {
323	                  hookEventName: 'PreToolUse',
324	                  permissionDecision: 'deny',
325	                  permissionDecisionReason: markerMsg,
326	                },
327	              }));
328	              process.exit(2);
329	            }
330	          }
331	        }
332	      }
333	    }
334	
335	    // -----------------------------------------------------------------------
336	    // W-AC-4 (v2.2.21): non-PM/non-curate-runner Agent() tool block.
337	    //
338	    // Anti-pattern #3: a non-PM agent declaring Agent() in its tools allowlist
339	    // creates a rogue orchestration path outside the PM's planning loop.
340	    // Only the pm and curate-runner roles are authorized to call Agent().
341	    //
342	    // Detection: the hook payload carries `agent_type` (the calling agent's
343	    // role). If it is set, non-empty, and NOT pm/curate-runner, block.
344	    // Absent agent_type (orchestrator session) is allowed through — the parent
345	    // session has no role restriction.
346	    //
347	    // Kill switch: ORCHESTRAY_NON_PM_AGENT_GATE_DISABLED=1.
348	    // Fail-open: any error in this block allows the spawn.
349	    // -----------------------------------------------------------------------
350	    {
351	      try {
352	        const callerRole = event.agent_type || null;
353	        const AUTHORIZED_AGENT_ROLES = new Set(['pm', 'curate-runner']);
354	        if (
355	          callerRole &&
356	          !AUTHORIZED_AGENT_ROLES.has(callerRole) &&
357	          process.env.ORCHESTRAY_NON_PM_AGENT_GATE_DISABLED !== '1'
358	        ) {
359	          const nonPmMsg =
360	            "[orchestray] gate-agent-spawn: non_pm_agent_declares_agent_tool — " +
361	            "agent role '" + callerRole + "' is not authorized to call Agent(). " +
362	            "Only 'pm' and 'curate-runner' may spawn sub-agents. " +
363	            "Emergency override: set ORCHESTRAY_NON_PM_AGENT_GATE_DISABLED=1.";
364	          process.stderr.write(nonPmMsg + '\n');
365	          try {
366	            writeEvent({
367	              type:           'non_pm_agent_spawn_blocked',
368	              version:        1,
369	              schema_version: 1,
370	              timestamp:      new Date().toISOString(),
371	              caller_role:    callerRole,
372	              tool_name:      toolName,
373	              source:         'gate-agent-spawn',
374	            }, { cwd });
375	          } catch (_npEvErr) { /* fail-open on emit */ }
376	          process.stdout.write(JSON.stringify({
377	            hookSpecificOutput: {
378	              hookEventName: 'PreToolUse',
379	              permissionDecision: 'deny',
380	              permissionDecisionReason: nonPmMsg,
381	            },
382	          }));
383	          process.exit(2);
384	        }
385	      } catch (_nonPmErr) {
386	        // Fail-open: any error → allow.
387	      }
388	    }
389	
390	    // Not in an orchestration — no gating, allow freely
391	    if (!fs.existsSync(orchFile)) {
392	      process.exit(0);
393	    }
394	
395	    // -----------------------------------------------------------------------
396	    // v2.2.13 W4 (G-05): orchestration_start emit on first spawn per orch.
397	    // Atomic create-and-fail-if-exists closes the parallel-spawn TOCTOU race
398	    // identified in W3-review P1-6.
399	    // -----------------------------------------------------------------------
400	    {
401	      let orchIdForStart = null;
402	      try {
403	        const oc = JSON.parse(fs.readFileSync(orchFile, 'utf8'));
404	        if (oc && oc.orchestration_id) orchIdForStart = oc.orchestration_id;
405	      } catch (_e) { /* fail-open */ }
406	
407	      if (orchIdForStart && process.env.ORCHESTRAY_ORCH_LIFECYCLE_EMIT_DISABLED !== '1') {
408	        const sentinelPath = path.join(cwd, '.orchestray', 'state',
409	          `orchestration-start-emitted.${orchIdForStart}`);
410	        let won = false;
411	        try {
412	          fs.writeFileSync(sentinelPath, '', { flag: 'wx' }); // atomic create
413	          won = true;
414	        } catch (e) {
415	          if (e && e.code !== 'EEXIST') {
416	            // Disk error / permissions — fail open; don't block the spawn.
417	          }
418	          // EEXIST: another parallel spawn already won; skip emit silently.
419	        }
420	        if (won) {
421	          try {
422	            writeEvent({
423	              event_type:       'orchestration_start',
424	              version:          1,
425	              orchestration_id: orchIdForStart,
426	              started_at:       new Date().toISOString(),
427	              schema_version:   1,
428	            }, { cwd });
429	          } catch (_e) { /* fail-open */ }
430	        }
431	      }
432	    }
433	
434	    // -----------------------------------------------------------------------
435	    // v2.2.9 B-5.3 — Group-boundary discipline gate.
436	    //
437	    // Per W1 F-PM-13: PM may spawn an agent for a task in a future group while
438	    // the current group has incomplete tasks. v2.2.8 had this as prose-only.
439	    // Mechanical replacement: read .orchestray/state/orchestration.md for
440	    // current_group, read .orchestray/state/task-graph.md for the group→task
441	    // mapping, and reject any spawn whose target task_id lives in a STRICTLY
442	    // LATER group while the current group has any non-completed task.
443	    //
444	    // Default-on. Kill switch: ORCHESTRAY_GROUP_BOUNDARY_GATE_DISABLED=1.
445	    // When the kill switch is ON, the gate is permissive but a
446	    // `group_boundary_violation` is STILL emitted on detected boundary jumps
447	    // so the violation count is observable.
448	    //
449	    // Fail-open: if either state file is missing/unparseable, exit 0 (no scope
450	    // to check).

