#!/usr/bin/env node
'use strict';

/**
 * PreToolUse:Agent hook — enforces model routing during orchestrations.
 *
 * Blocks any Agent() call that omits the `model` parameter or uses
 * model="inherit" while an orchestration is active. Fails open on all
 * unexpected errors so a broken hook never blocks legitimate work.
 *
 * 2.0.12 additions:
 *   - Explicit dispatch allowlist replaces the `toolName !== 'Agent'` fast-exit.
 *     Known agent-dispatch names: {Agent, Explore, Task}.
 *     Known skip names: {Bash, Read, Edit, Glob, Grep, Write, NotebookEdit,
 *       WebFetch, WebSearch, TodoWrite}. Unknown names are handled by
 *     `mcp_enforcement.unknown_tool_policy` (default: "block").
 *   - `global_kill_switch` short-circuits before ANY 2.0.12 check. Routing.jsonl
 *     (2.0.11) validation still runs on known dispatch names.
 *   - MCP checkpoint pre-decomposition gate: after routing.jsonl validation,
 *     verifies that the PM called the required pre-decomposition MCP tools
 *     (pattern_find, kb_search, history_find_similar_tasks) for this
 *     orchestration_id before the first Agent() spawn.
 *
 * Input:  JSON on stdin (Claude Code PreToolUse hook payload)
 * Output: exit 0 (allow) or exit 2 (block) with stderr message
 */

const fs = require('fs');
const path = require('path');
const { resolveSafeCwd } = require('./_lib/resolve-project-cwd');
const { getCurrentOrchestrationFile } = require('./_lib/orchestration-state');
const { getRoutingFilePath, findRoutingEntry, readRoutingEntries } = require('./_lib/routing-lookup');
const { loadMcpEnforcement, loadRoutingGateConfig, loadAntiPatternGateConfig, loadPatternDecayConfig } = require('./_lib/config-schema');
const {
  REQUIRED_PRE_DECOMPOSITION_TOOLS,
  getCheckpointFilePath,
  findCheckpointsForOrchestration,
  missingRequiredToolsFromRows,
} = require('./_lib/mcp-checkpoint');
const { atomicAppendJsonl } = require('./_lib/atomic-append');
const { writeEvent }        = require('./_lib/audit-event-writer');
const { MAX_INPUT_BYTES } = require('./_lib/constants');
const { readCache: readCustomAgentsCache } = require('./_lib/custom-agents');
const { CANONICAL_AGENTS } = require('./_lib/canonical-agents');
const { readHookInputRaw } = require('./_lib/hook-stdin');

const VALID_TIERS = ['fable', 'haiku', 'sonnet', 'opus'];

function isValidModel(model) {
  const m = model.toLowerCase();
  return VALID_TIERS.some(tier => m.includes(tier));
}

// v2.2.9 B-5.3: gate stdin reader behind require.main check so test imports
// of helper exports (computeGroupBoundaryViolation, parseTaskGraphGroups,
// compareGroupOrder) don't block on stdin.
if (require.main === module) {
  let input = '';
  input = readHookInputRaw();
  if (input.length > MAX_INPUT_BYTES) {
    process.stderr.write('[orchestray] hook stdin exceeded ' + MAX_INPUT_BYTES + ' bytes; aborting\n');
    process.exit(0);
  }
  setImmediate(() => {
  try {
    const event = JSON.parse(input);

    // Explicit dispatch allowlist. 2.0.12 closes the Explore/Task bypass by routing
    // known agent-dispatch tool names through this gate. Anything else is either a
    // known non-agent built-in (Bash, Read, Edit, Glob, Grep, Write — skip) or an
    // unknown name (fail-closed by default per unknown_tool_policy; user can
    // override in .orchestray/config.json).
    const toolName = event.tool_name || (event.tool_input && event.tool_input.tool) || '';

    const AGENT_DISPATCH_ALLOWLIST = new Set(['Agent', 'Explore', 'Task']);
    const SKIP_ALLOWLIST = new Set([
      'Bash', 'Read', 'Edit', 'Glob', 'Grep', 'Write',
      'NotebookEdit', 'WebFetch', 'WebSearch', 'TodoWrite',
    ]);

    if (SKIP_ALLOWLIST.has(toolName)) {
      process.exit(0);
    }

    // Not a known agent-dispatch OR skip tool — defer decision to unknown_tool_policy
    // AFTER config is loaded (see below).
    const isKnownDispatch = AGENT_DISPATCH_ALLOWLIST.has(toolName);

    const cwd = resolveSafeCwd(event.cwd);
    const mcpEnforcement = loadMcpEnforcement(cwd);

    // Global kill switch — short-circuits before ANY 2.0.12 check. Routing.jsonl
    // (2.0.11) validation still runs on known dispatches. D5 property.
    if (mcpEnforcement.global_kill_switch === true && isKnownDispatch) {
      // In kill-switch mode, we still enforce 2.0.11 model-validity checks on
      // known dispatches but skip the new 2.0.12 MCP-checkpoint gate entirely.
      // Emit kill_switch_activated event for observability (I-SE-3).
      try {
        writeEvent({
          type:           'kill_switch_activated',
          version:        1,
          schema_version: 1,
          timestamp:      new Date().toISOString(),
          switch_name:    'global_kill_switch',
          tool_name:      toolName,
          source:         'gate-agent-spawn',
        }, { cwd });
      } catch (_ksEvErr) { /* fail-open */ }
      // Fall through to the existing routing.jsonl validation below.
    } else if (mcpEnforcement.global_kill_switch === true) {
      // Kill switch on AND unknown tool — just exit 0 (degraded to 2.0.11 behavior).
      // Emit kill_switch_activated event for observability (I-SE-3).
      try {
        writeEvent({
          type:           'kill_switch_activated',
          version:        1,
          schema_version: 1,
          timestamp:      new Date().toISOString(),
          switch_name:    'global_kill_switch',
          tool_name:      toolName,
          source:         'gate-agent-spawn',
        }, { cwd });
      } catch (_ksEvErr) { /* fail-open */ }
      process.exit(0);
    } else {
      // Unknown-tool policy (only when NOT in kill-switch mode)
      if (!isKnownDispatch) {
        const policy = mcpEnforcement.unknown_tool_policy || 'block';
        if (policy === 'allow') {
          process.exit(0);
        }
        if (policy === 'warn') {
          process.stderr.write(
            "[orchestray] unknown tool name '" + toolName + "' in PreToolUse — " +
            "allowing per unknown_tool_policy=warn. Add to AGENT_DISPATCH_ALLOWLIST " +
            "or SKIP_ALLOWLIST in bin/gate-agent-spawn.js to silence.\n"
          );
          process.exit(0);
        }
        // policy === 'block' (default per Q1)
        process.stderr.write(
          "[orchestray] unknown tool name '" + toolName + "' in PreToolUse — " +
          "blocking per unknown_tool_policy=block. If this is a legitimate Claude Code " +
          "built-in, add it to AGENT_DISPATCH_ALLOWLIST (to gate it) or SKIP_ALLOWLIST " +
          "(to skip gating) in bin/gate-agent-spawn.js. Emergency override: set " +
          "mcp_enforcement.unknown_tool_policy to 'warn' in .orchestray/config.json.\n"
        );
        process.exit(2);
      }
    }

    // From here on: toolName is a known agent-dispatch name (Agent, Explore, or Task),
    // or kill-switch mode is active. Proceed with 2.0.11 routing.jsonl validation.

    const orchFile = getCurrentOrchestrationFile(cwd);

    // -----------------------------------------------------------------------
    // v2.3.1 §6.2: Custom-agents spawn gate — fail-closed for unknown types.
    //
    // For Agent() calls only (not Explore/Task which carry no subagent_type):
    // if the requested subagent_type is not a shipped canonical agent AND not in
    // the custom-agents cache written by bin/discover-custom-agents.js, reject.
    //
    // This is the sole authority on which agent types are allowed — the PM
    // frontmatter no longer carries a parenthetical allowlist.
    //
    // Fail-open: any error in the cache-read path allows the spawn.
    // Kill switches: ORCHESTRAY_DISABLE_CUSTOM_AGENTS (env) or
    //   custom_agents.enabled: false (config) — per design §17.1/§17.2.
    //   No emergency fail-open override exists by design (fail-closed is the
    //   security requirement; master switch is the only opt-out).
    // -----------------------------------------------------------------------
    if (toolName === 'Agent') {
      try {
        const gateToolInput = event.tool_input || {};
        const gateSubagentType = gateToolInput.subagent_type || '';
        if (gateSubagentType && !CANONICAL_AGENTS.has(gateSubagentType)) {
          // Not a shipped canonical agent — check custom-agents cache.
          // readCustomAgentsCache never throws and never returns null; it returns
          // a safe empty struct {agents: []} on any read/parse failure.
          let isAllowed = false;
          try {
            const cache = readCustomAgentsCache(cwd);
            if (Array.isArray(cache.agents)) {
              isAllowed = cache.agents.some(a => a && a.name === gateSubagentType);
            }
            // §3.3: stderr hint when cache is >7 days old (does not invalidate).
            if (cache.discovered_at) {
              const ageMs = Date.now() - new Date(cache.discovered_at).getTime();
              if (Number.isFinite(ageMs) && ageMs > 7 * 24 * 60 * 60 * 1000) {
                process.stderr.write(
                  '[orchestray] custom-agents: cache is >7 days old; ' +
                  'restart Claude Code to refresh discovered agents\n'
                );
              }
            }
          } catch (_cacheErr) {
            // Cache read failed — fail-closed: treat as unknown.
          }
          if (!isAllowed) {
            const rejectMsg =
              '[orchestray] gate-agent-spawn: unknown subagent_type "' + gateSubagentType + '" — ' +
              'not a shipped agent role and not found in the custom-agents cache. ' +
              'To add a custom agent, create: ' +
              '~/.claude/orchestray/custom-agents/' + gateSubagentType + '.md ' +
              'then restart the Claude Code session. ' +
              'To disable custom-agent gating entirely, set ORCHESTRAY_DISABLE_CUSTOM_AGENTS=1.';
            process.stderr.write(rejectMsg + '\n');
            try {
              writeEvent({
                type:            'custom_agents_spawn_rejected',
                version:         1,
                schema_version:  1,
                timestamp:       new Date().toISOString(),
                subagent_type:   gateSubagentType,
                source:          'gate-agent-spawn',
              }, { cwd });
            } catch (_evErr) { /* fail-open on emit */ }
            process.stdout.write(JSON.stringify({
              hookSpecificOutput: {
                hookEventName: 'PreToolUse',
                permissionDecision: 'deny',
                permissionDecisionReason: rejectMsg,
              },
            }));
            process.exit(2);
          }
        }
      } catch (_customGateErr) {
        // Fail-open: any unexpected error allows the spawn.
      }
    }

    // P3.3 (v2.2.0): orchestray-housekeeper spawn gate — Clause 3 + Clause 5.
    // Refuse if quarantine sentinel exists (drift detector controlled),
    // env kill switch is set, or config flag is false. Runs BEFORE the
    // orchestration check so it applies in any session state.
    {
      const earlyToolInput = event.tool_input || {};
      const earlySubagentType = earlyToolInput.subagent_type || '';
      if (earlySubagentType === 'orchestray-housekeeper') {
        const sentinelPath = path.join(cwd, '.orchestray', 'state', 'housekeeper-quarantined');
        if (fs.existsSync(sentinelPath)) {
          const quarantineMsg =
            '[orchestray] gate-agent-spawn: orchestray-housekeeper spawn blocked — ' +
            'quarantine sentinel present. Resolve baseline drift before re-enabling. ' +
            'See agents/pm-reference/haiku-routing.md §23f.';
          process.stderr.write(quarantineMsg + '\n');
          process.stdout.write(JSON.stringify({
            hookSpecificOutput: {
              hookEventName: 'PreToolUse',
              permissionDecision: 'deny',
              permissionDecisionReason: quarantineMsg,
            },
          }));
          process.exit(2);
        }
        if (process.env.ORCHESTRAY_HOUSEKEEPER_DISABLED === '1') {
          const envMsg =
            '[orchestray] gate-agent-spawn: orchestray-housekeeper disabled by env ' +
            '(ORCHESTRAY_HOUSEKEEPER_DISABLED=1).';
          process.stderr.write(envMsg + '\n');
          process.stdout.write(JSON.stringify({
            hookSpecificOutput: {
              hookEventName: 'PreToolUse',
              permissionDecision: 'deny',
              permissionDecisionReason: envMsg,
            },
          }));
          process.exit(2);
        }
        try {
          const cfgRaw = fs.readFileSync(path.join(cwd, '.orchestray', 'config.json'), 'utf8');
          const cfg = JSON.parse(cfgRaw);
          if (cfg && cfg.haiku_routing &&
              cfg.haiku_routing.housekeeper_enabled === false) {
            const cfgMsg =
              '[orchestray] gate-agent-spawn: orchestray-housekeeper disabled in config ' +
              '(haiku_routing.housekeeper_enabled = false).';
            process.stderr.write(cfgMsg + '\n');
            process.stdout.write(JSON.stringify({
              hookSpecificOutput: {
                hookEventName: 'PreToolUse',
                permissionDecision: 'deny',
                permissionDecisionReason: cfgMsg,
              },
            }));
            process.exit(2);
          }
        } catch (_cfgErr) { /* fail-open — default-on per locked-scope D-5 */ }

        // S-009 (v2.2.0 fix-pass): housekeeper marker path-prefix check.
        // OQ-D1 (in-scope per design) — defence-in-depth against a
        // misaddressed [housekeeper: write <path>] marker. The housekeeper
        // tool list (Read, Glob) limits damage to "read sensitive file →
        // return bytes in Structured Result", but the gate is the cleanest
        // place to enforce that any `[housekeeper: write <path>]` marker
        // names a path under `.orchestray/kb/artifacts/`. Reject otherwise.
        // Non-`write` markers (regen-schema-shadow, rollup-recompute) carry
        // no path and pass through.
        const description = (earlyToolInput.description || '');
        if (typeof description === 'string') {
          const writeMarker = description.match(/\[housekeeper:\s*write\s+([^\]]+)\]/);
          if (writeMarker && writeMarker[1]) {
            const requestedPath = writeMarker[1].trim();
            const ARTIFACTS_PREFIX = path.join('.orchestray', 'kb', 'artifacts');
            const artifactsAbs = path.resolve(cwd, ARTIFACTS_PREFIX);
            const requestedAbs = path.isAbsolute(requestedPath)
              ? path.resolve(requestedPath)
              : path.resolve(cwd, requestedPath);
            const inside = requestedAbs === artifactsAbs ||
              requestedAbs.startsWith(artifactsAbs + path.sep);
            if (!inside) {
              const markerMsg =
                '[orchestray] gate-agent-spawn: orchestray-housekeeper marker path ' +
                'outside .orchestray/kb/artifacts/ — refusing to spawn. ' +
                'Marker path: ' + JSON.stringify(requestedPath) + '. ' +
                'Per OQ-D1 of locked-scope D-5, write markers MUST stay within ' +
                'the artifacts directory.';
              process.stderr.write(markerMsg + '\n');
              process.stdout.write(JSON.stringify({
                hookSpecificOutput: {
                  hookEventName: 'PreToolUse',
                  permissionDecision: 'deny',
                  permissionDecisionReason: markerMsg,
                },
              }));
              process.exit(2);
            }
          }
        }
      }
    }

    // -----------------------------------------------------------------------
    // W-AC-4 (v2.2.21): non-PM/non-curate-runner Agent() tool block.
    //
    // Anti-pattern #3: a non-PM agent declaring Agent() in its tools allowlist
    // creates a rogue orchestration path outside the PM's planning loop.
    // Only the pm and curate-runner roles are authorized to call Agent().
    //
    // Detection: the hook payload carries `agent_type` (the calling agent's
    // role). If it is set, non-empty, and NOT pm/curate-runner, block.
    // Absent agent_type (orchestrator session) is allowed through — the parent
    // session has no role restriction.
    //
    // Kill switch: ORCHESTRAY_NON_PM_AGENT_GATE_DISABLED=1.
    // Fail-open: any error in this block allows the spawn.
    // -----------------------------------------------------------------------
    {
      try {
        const callerRole = event.agent_type || null;
        const AUTHORIZED_AGENT_ROLES = new Set(['pm', 'curate-runner']);
        if (
          callerRole &&
          !AUTHORIZED_AGENT_ROLES.has(callerRole) &&
          process.env.ORCHESTRAY_NON_PM_AGENT_GATE_DISABLED !== '1'
        ) {
          const nonPmMsg =
            "[orchestray] gate-agent-spawn: non_pm_agent_declares_agent_tool — " +
            "agent role '" + callerRole + "' is not authorized to call Agent(). " +
            "Only 'pm' and 'curate-runner' may spawn sub-agents. " +
            "Emergency override: set ORCHESTRAY_NON_PM_AGENT_GATE_DISABLED=1.";
          process.stderr.write(nonPmMsg + '\n');
          try {
            writeEvent({
              type:           'non_pm_agent_spawn_blocked',
              version:        1,
              schema_version: 1,
              timestamp:      new Date().toISOString(),
              caller_role:    callerRole,
              tool_name:      toolName,
              source:         'gate-agent-spawn',
            }, { cwd });
          } catch (_npEvErr) { /* fail-open on emit */ }
          process.stdout.write(JSON.stringify({
            hookSpecificOutput: {
              hookEventName: 'PreToolUse',
              permissionDecision: 'deny',
              permissionDecisionReason: nonPmMsg,
            },
          }));
          process.exit(2);
        }
      } catch (_nonPmErr) {
        // Fail-open: any error → allow.
      }
    }

    // Not in an orchestration — no gating, allow freely
    if (!fs.existsSync(orchFile)) {
      process.exit(0);
    }

    // -----------------------------------------------------------------------
    // v2.2.13 W4 (G-05): orchestration_start emit on first spawn per orch.
    // Atomic create-and-fail-if-exists closes the parallel-spawn TOCTOU race
    // identified in W3-review P1-6.
    // -----------------------------------------------------------------------
    {
      let orchIdForStart = null;
      try {
        const oc = JSON.parse(fs.readFileSync(orchFile, 'utf8'));
        if (oc && oc.orchestration_id) orchIdForStart = oc.orchestration_id;
      } catch (_e) { /* fail-open */ }

      if (orchIdForStart && process.env.ORCHESTRAY_ORCH_LIFECYCLE_EMIT_DISABLED !== '1') {
        const sentinelPath = path.join(cwd, '.orchestray', 'state',
          `orchestration-start-emitted.${orchIdForStart}`);
        let won = false;
        try {
          fs.writeFileSync(sentinelPath, '', { flag: 'wx' }); // atomic create
          won = true;
        } catch (e) {
          if (e && e.code !== 'EEXIST') {
            // Disk error / permissions — fail open; don't block the spawn.
          }
          // EEXIST: another parallel spawn already won; skip emit silently.
        }
        if (won) {
          try {
            writeEvent({
              event_type:       'orchestration_start',
              version:          1,
              orchestration_id: orchIdForStart,
              started_at:       new Date().toISOString(),
              schema_version:   1,
            }, { cwd });
          } catch (_e) { /* fail-open */ }
        }
      }
    }

    // -----------------------------------------------------------------------
    // v2.2.9 B-5.3 — Group-boundary discipline gate.
    //
    // Per W1 F-PM-13: PM may spawn an agent for a task in a future group while
    // the current group has incomplete tasks. v2.2.8 had this as prose-only.
    // Mechanical replacement: read .orchestray/state/orchestration.md for
    // current_group, read .orchestray/state/task-graph.md for the group→task
    // mapping, and reject any spawn whose target task_id lives in a STRICTLY
    // LATER group while the current group has any non-completed task.
    //
    // Default-on. Kill switch: ORCHESTRAY_GROUP_BOUNDARY_GATE_DISABLED=1.
    // When the kill switch is ON, the gate is permissive but a
    // `group_boundary_violation` is STILL emitted on detected boundary jumps
    // so the violation count is observable.
    //
    // Fail-open: if either state file is missing/unparseable, exit 0 (no scope
    // to check).

