175	 *
176	 * Primary source for agent_type: event.agent_type.
177	 * Model priority: staged spawn info > .meta.json > transcript first-assistant > null.
178	 *
179	 * @param {object} event
180	 * @param {string} cwd
181	 */
182	function handleStart(event, cwd) {
183	  const agentId   = event.agent_id   || null;
184	  const agentType = event.agent_type || null;
185	  const transcriptPath = validateTranscriptPath(event.agent_transcript_path, cwd);
